WITH p AS (SELECT coalesce(%s::text,'') ma_vt,coalesce(%s::text,'') ma_kho,coalesce(%s::text,'') ma_lo,coalesce(%s::text,'') status_qc,%s::integer uid,%s::integer lim),s AS (SELECT p.*,u.user_id ok,coalesce(u.ds_branchs,'') bs,coalesce(u.is_super,0)=1 OR(coalesce(u.ds_branchs,'')='' AND coalesce(u.ds_stocks,'')='') unrestricted FROM p LEFT JOIN public.userinfo u ON u.user_id=p.uid),q AS (SELECT e->>'ma_vt' ma_vt,e->>'ma_lo' ma_lo,a.ma_kho,a.ma_vi_tri,a.status_qc,sum((e->>'so_luong')::numeric) ton_vi_tri FROM public.intem_log a CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(a.data_tem::jsonb)='array' THEN a.data_tem::jsonb ELSE '[]'::jsonb END) e CROSS JOIN s WHERE s.ok IS NOT NULL AND a.nxt=1 AND a.status='1' AND(s.ma_vt='' OR e->>'ma_vt'=ANY(string_to_array(s.ma_vt,',')))AND(s.ma_kho='' OR a.ma_kho=ANY(string_to_array(s.ma_kho,',')))AND(s.ma_lo='' OR e->>'ma_lo'=ANY(string_to_array(s.ma_lo,',')))AND(s.status_qc='' OR a.status_qc::text=ANY(string_to_array(s.status_qc,',')))AND(s.unrestricted OR EXISTS(SELECT 1 FROM public.dmkho k WHERE k.ma_kho=a.ma_kho AND k.ma_dvcs=ANY(string_to_array(s.bs,',')))) GROUP BY e->>'ma_vt',e->>'ma_lo',a.ma_kho,a.ma_vi_tri,a.status_qc) SELECT q.ma_vt,v.ten_vt,v.dvt,v.nh_vt6,q.ma_lo,q.ma_kho,q.ma_vi_tri,q.ton_vi_tri,coalesce(o.form_name,q.status_qc::text) status_qc,count(*) OVER() total FROM q JOIN public.dmvt v ON v.ma_vt=q.ma_vt LEFT JOIN public.sys_listoptions o ON o.form='OQC' AND o.form_type='TYPE_ST' AND o.form_value=q.status_qc::text ORDER BY q.ma_vt,q.ma_lo,q.ma_kho,q.ma_vi_tri,q.status_qc LIMIT(SELECT lim FROM p);
